<?php
namespace Tests\Feature;
use App\Domain\{Access,AudioStore,RecorderHandoffs};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Tests\TestCase;

final class RecorderHandoffsTest extends TestCase {
 use DatabaseTransactions;
 private object $owner; private object $target; private int $lesson; private RecorderHandoffs $service;
 protected function setUp():void {parent::setUp();$this->owner=$this->actor();$this->target=$this->actor();$c=DB::table('courses')->insertGetId(['name'=>'Handoff fixture']);$this->lesson=DB::table('lessons')->insertGetId(['course_id'=>$c,'creator_id'=>$this->owner->id,'recorder_user_id'=>$this->owner->id,'recorder_connection'=>'old-device','recorder_epoch'=>2,'status'=>'live','target_language'=>'zh','lease_until'=>now()->addSeconds(20),'name'=>'Transfer','idempotency_key'=>(string)Str::uuid()]);$this->service=new RecorderHandoffs;}
 private function actor():object{$id=DB::table('users')->insertGetId(['student_id'=>'fixture-'.Str::uuid(),'name'=>'Їван','password'=>'unused','role'=>'user','must_change_password'=>false]);return Access::user($id);}
 private function invite():object{return $this->service->create($this->lesson,$this->owner,'old-device',$this->target,'new-device','invite',(string)Str::uuid());}
 public function test_denied_microphone_keeps_old_device_and_epoch():void{$h=$this->invite();$this->service->respond($this->lesson,$this->target,'new-device',$h->id,'accept');$this->service->prepared($this->lesson,$this->target,'new-device',$h->id,false);$l=DB::table('lessons')->find($this->lesson);self::assertSame('old-device',$l->recorder_connection);self::assertSame(2,$l->recorder_epoch);self::assertSame('failed',DB::table('recorder_handoffs')->find($h->id)->status);}
 public function test_preparation_atomically_revokes_old_epoch_and_cancels_competitors():void{$h=$this->invite();$competitor=$this->invite();$this->service->respond($this->lesson,$this->target,'new-device',$h->id,'accept');$previous=$this->service->prepared($this->lesson,$this->target,'new-device',$h->id,true);self::assertSame('live',$previous->status);$l=DB::table('lessons')->find($this->lesson);self::assertSame((int)$this->target->id,(int)$l->recorder_user_id);self::assertSame(3,$l->recorder_epoch);self::assertNull($l->recorder_connection);self::assertSame('paused',$l->status);self::assertSame('cancelled',DB::table('recorder_handoffs')->find($competitor->id)->status);$this->expectExceptionMessage('recorder_stale');(new AudioStore)->accept($this->lesson,$this->owner->id,'old-device',2,0,str_repeat("\0",3200));}
 public function test_other_device_of_same_target_cannot_accept():void{$h=$this->invite();$this->expectExceptionMessage('forbidden');$this->service->respond($this->lesson,$this->target,'wrong-device',$h->id,'accept');}
 public function test_request_approval_requires_current_owner_device():void{$h=$this->service->create($this->lesson,$this->target,'new-device',$this->owner,'old-device','request',(string)Str::uuid());$this->service->respond($this->lesson,$this->owner,'old-device',$h->id,'accept');$this->service->prepared($this->lesson,$this->target,'new-device',$h->id,true);self::assertSame((int)$this->target->id,(int)DB::table('lessons')->find($this->lesson)->recorder_user_id);}
 public function test_paused_transfer_preserves_pause_and_media_time():void{DB::table('lessons')->where('id',$this->lesson)->update(['status'=>'paused','recorder_connection'=>null,'media_samples'=>51200]);$h=$this->invite();$this->service->respond($this->lesson,$this->target,'new-device',$h->id,'accept');$this->service->prepared($this->lesson,$this->target,'new-device',$h->id,true);$l=DB::table('lessons')->find($this->lesson);self::assertSame('paused',$l->status);self::assertSame(51200,(int)$l->media_samples);}
 public function test_expired_invite_and_ended_lesson_cannot_switch():void{$h=$this->invite();DB::table('recorder_handoffs')->where('id',$h->id)->update(['expires_at'=>now()->subSeconds(1)]);$this->service->expire();self::assertSame('expired',DB::table('recorder_handoffs')->find($h->id)->status);$this->expectExceptionMessage('handoff_stale');$this->service->respond($this->lesson,$this->target,'new-device',$h->id,'accept');}
 public function test_offline_grace_window_blocks_early_takeover():void{DB::table('lessons')->where('id',$this->lesson)->update(['recorder_connection'=>null,'status'=>'paused','recorder_offline_at'=>now()]);$this->expectExceptionMessage('recorder_recovery_window');$this->service->takeover($this->lesson,$this->target,false,false);}
 public function test_confirmed_expired_offline_holder_can_be_taken_over():void{DB::table('lessons')->where('id',$this->lesson)->update(['recorder_connection'=>null,'status'=>'paused','recorder_offline_at'=>now()->subSeconds(45)]);$this->service->takeover($this->lesson,$this->target,false,false);self::assertSame((int)$this->target->id,(int)DB::table('lessons')->find($this->lesson)->recorder_user_id);self::assertSame(1,DB::table('audit')->where('lesson_id',$this->lesson)->where('action','recorder_offline_takeover')->count());}
 public function test_guest_and_forced_change_accounts_cannot_receive_rights():void{$this->target->must_change_password=true;$this->expectExceptionMessage('password_change_required');$this->invite();}
 public function test_cancel_is_idempotent_operation_safe_to_reject_on_repetition():void{$h=$this->invite();$this->service->respond($this->lesson,$this->owner,'old-device',$h->id,'cancel');self::assertSame('cancelled',DB::table('recorder_handoffs')->find($h->id)->status);$this->expectExceptionMessage('handoff_stale');$this->service->respond($this->lesson,$this->target,'new-device',$h->id,'accept');}
 public function test_switch_during_upstream_handshake_cannot_orphan_a_billing_session():void{DB::table('lessons')->where('id',$this->lesson)->update(['translation_status'=>'connecting']);$this->expectExceptionMessage('model_session_busy');$this->invite();}
}
